const prompt = msg.prompt || (typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload));
let cmd = `agy -p ${JSON.stringify(prompt)} --dangerously-skip-permissions`;

if (msg.schema) {
    const schemaStr = typeof msg.schema === 'object' ? JSON.stringify(msg.schema) : msg.schema;
    cmd += ` --json-schema ${JSON.stringify(schemaStr)} --output-format json`;
}

msg.payload = cmd;
return msg;

let parsed;
try {
    parsed = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    parsed = { response: msg.payload };
}

let result = parsed.structured_output;
if (!result && parsed.response) {
    try {
        result = typeof parsed.response === 'string' ? JSON.parse(parsed.response) : parsed.response;
    } catch (e) {
        result = parsed.response;
    }
}

msg.payload = result || parsed;
return msg;

// 🔑 核心一：空內容防呆
const text = (msg.payload || '').toString().trim();
if (!text || text.length < 5) { node.warn('剪貼簿為空，跳過'); return null; }

// 🔑 核心二：截取前 800 字元脫水
const cleanText = text.substring(0, 800);

// 🔑 核心三：JSON Schema 強制約束輸出格式
msg.schema = {
  type: 'object',
  required: ['content_type', 'summary_zh', 'action_suggestion'],
  properties: {
    content_type:      { type: 'string' },
    summary_zh:        { type: 'string' },
    action_suggestion: { type: 'string' }
  }
};

// 🔑 核心四：Prompt 明確指定每個欄位應填入的「結果本身」，而非說明過程
msg.prompt = `你是智慧剪貼簿管家。請分析以下文字並回傳 JSON，欄位規定如下：
- content_type：文字類型，只能填 ERROR_LOG / CODE_SNIPPET / ENGLISH_TEXT / GENERAL 其中之一
- summary_zh：【直接寫結果，不要描述你在做什麼】英文→翻譯成正體中文；報錯→一句話說明錯誤原因；程式碼→說明功能
- action_suggestion：具體的下一步建議（一到兩句話）

分析文字：
"""
${cleanText}
"""`;
return msg;

const data = msg.payload || {};
const summary = String(data.summary_zh || '已完成解析').replace(/'/g, "''");
const advice  = String(data.action_suggestion || '').replace(/'/g, "''");
const ctype   = String(data.content_type || '內容解析').replace(/'/g, "''");

// 🔑 Set-Clipboard：用 [char]10 串接換行（PowerShell 單引號字串不解析 `n）
// 🔑 Toast 標題/內容：用 `n 在雙引號字串中換行（Toast 文字框）
const psCmd = [
  '$nl=[char]10',
  `Set-Clipboard -Value ('【AI 剪貼簿解析】'+$nl+'📌 摘要: ${summary}'+$nl+'💡 建議: ${advice}')`,
  '[Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime] > $null',
  '$template = [Windows.UI.Notifications.ToastNotificationManager]::GetTemplateContent([Windows.UI.Notifications.ToastTemplateType]::ToastText02)',
  '$textNodes = $template.GetElementsByTagName(\'text\')',
  `$textNodes.Item(0).AppendChild($template.CreateTextNode('📋 AI 剪貼簿: ${ctype}')) > $null`,
  `$textNodes.Item(1).AppendChild($template.CreateTextNode('${summary}')) > $null`,
  `[Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier('AI 剪貼簿管家').Show([Windows.UI.Notifications.ToastNotification]::new($template))`
].join('; ');

msg.payload = `powershell -NoProfile -WindowStyle Hidden -Command "${psCmd}"`;
return msg;
